window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your best friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":6.14},{"id":"n03","text":"All the police have is a blurry photo of the robber.","at":12.78,"t0":6.39,"t1":9.155},{"id":"n03a","text":"All he has is you.","at":18.81,"t0":9.405,"t1":10.465},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":21.53,"t0":10.765,"t1":13.685},{"id":"n03b","text":"But you don't really remember, because for you it was just another Tuesday.","at":29.97,"t0":14.985,"t1":18.885},{"id":"f01","text":"Think, yaar! We were at the chai stall, in the rain! You had ginger chai, you paid twenty rupees!","at":39.47,"t0":19.735,"t1":25.605},{"id":"f01r","text":"Don't you remember?","at":51.81,"t0":25.905,"t1":27.19},{"id":"n04","text":"And now you do.","at":54.98,"t0":27.49,"t1":28.495},{"id":"o02","text":"He says you two were at a chai stall. So what did you drink?","at":57.69,"t0":28.845,"t1":32.44},{"id":"o03","text":"How much did you pay?","at":67.28,"t0":33.64,"t1":35.31},{"id":"o04","text":"Same as his statement.","at":72.82,"t0":36.41,"t1":38.44},{"id":"n06","text":"Everything you know about that night, he told you.","at":78.28,"t0":39.14,"t1":41.54},{"id":"n06b","text":"So where was he, really?","at":84.48,"t0":42.24,"t1":43.47},{"id":"n07","text":"He was here.","at":88.74,"t0":44.37,"t1":45.195},{"id":"o05","text":"Alibi confirmed. He can go.","at":92.39,"t0":46.195,"t1":48.745},{"id":"n08","text":"You just set a robber free.","at":98.49,"t0":49.245,"t1":50.62},{"id":"n09","text":"You were never at that stall. He needed you to forget.","at":102.24,"t0":51.12,"t1":54.075},{"id":"f02","text":"Thanks, yaar. Next time, I'll pay.","at":109.55,"t0":54.775,"t1":56.955},{"id":"n11","text":"Would your best friend lie for you? Send them this: if anyone asks, I was with you last Tuesday.","at":115.11,"t0":57.555,"t1":62.825},{"id":"n12","text":"But first: what's hanging from his wrist?","at":129.15,"t0":64.575,"t1":66.71}];
